-- postpartum week 34: Carbohydrate, the fuel your body runs on first
insert into nourish_week_content
  (stage, week_number, trimester, phase_label, theme_title, mantra,
   why_it_matters, condition_notes, meat_fish_eggs_note, using_meals_note,
   days, reflection, looking_ahead)
values
  ('postpartum',
   34,
   NULL,
   'Phase 4 of 6 — Settling into strength',
   'Carbohydrate, the fuel your body runs on first',
   '"Not something to fear or eliminate — carbohydrate is ordinary fuel, and how much, what kind, and when can vary from mother to mother."',
   'Carbohydrate does not need to be feared or eliminated. The amount, type and timing that suit you can vary — especially if you are managing blood glucose. Carbohydrate is broken down into glucose, an important and readily available energy source for the brain and muscles. During lactation, glucose is also used in producing lactose, the main carbohydrate in breast milk. Reference intakes: The US National Academies set a Recommended Dietary Allowance of 130 g a day for non-pregnant adults, 175 g during pregnancy and 210 g during lactation. These values are designed to cover the needs of nearly all healthy people in each group; they are not gram targets that most mothers need to count. Where it naturally shows up: Ordinary Indian meals draw on many natural carbohydrate sources across the day — grains and millets, pulses, fruit, milk and curd, and starchy vegetables all contribute, usually adding up to considerably more than any reference figure without special planning. What this means for milk supply: The higher lactation reference does not mean that extra carbohydrate beyond a balanced diet produces more milk. Milk supply is influenced more directly by effective and frequent milk removal. A note on carbohydrate quality: Carbohydrate foods are not interchangeable. Whole grains, pulses, fruit, vegetables and dairy bring fibre, protein or micronutrients alongside carbohydrate, while sugary drinks and heavily refined snacks provide less sustained nourishment. This is about pattern and pairing — not labelling foods "good" or "bad". Every day below offers two distinct, individually balanced meals for each slot — pick whichever fits your day, your preferences, or what''s in your kitchen. If you have a diagnosed food allergy: If you have any diagnosed food allergy — including an allergy to egg, dairy, wheat, soy, peanut, tree nuts, seeds, fish or shellfish — avoid that food completely and choose an alternative you already tolerate. Do not trial a problem food to pursue this week''s nutrient. Do not automatically substitute seeds for nuts unless the seed is already known to be tolerated. If you are managing a health condition - If you have diabetes, persistent postpartum high blood glucose or a recent history of gestational diabetes: carbohydrate quantity, type and timing may need individual planning. Follow your prescribed carbohydrate plan if you have one. This general chart should not override glucose readings, medicines or postpartum testing advice. Do not cut carbohydrate drastically without clinical guidance. - If you have PCOS: pairing carbohydrate-rich foods with protein, fat, or fibre (dal with rice, or fruit with nuts) is a reasonable general approach for steadier blood sugar. This does not mean every woman with PCOS needs a low-carbohydrate diet — any structured plan should still go through your care team. - If you have a thyroid condition or high blood pressure: nothing about this week''s guidance changes specifically for you — continue your usual balanced diet and any care-team guidance already in place.',
   NULL,
   NULL,
   NULL,
   '[{"day_number": 1, "title": "Anchor", "notes": "Carbohydrate has been part of almost every meal in this series without ever getting its own week — today, that changes. Whatever you eat today, much of it is already carbohydrate: rice, roti, fruit, milk, dal. This isn''t a nutrient to chase; it''s one to simply keep including, alongside protein and vegetables or fruit.", "breakfast_a": "Moong-dal and vegetable chilla with a bowl of curd", "breakfast_b": "Egg-and-vegetable wrap with a small bowl of fruit", "lunch_a": "Rice, rajma curry, and a cucumber-tomato salad", "lunch_b": "Jowar roti with chicken curry and a carrot salad", "nourishment_break_a": "Roasted chana with a small bowl of fruit", "nourishment_break_b": "A glass of milk with two dates", "dinner_a": "Roti with a mixed-vegetable and paneer curry", "dinner_b": "Rice with a fish curry and a stir-fried vegetable", "still_hungry": "A small bowl of curd with a few nuts"}, {"day_number": 2, "title": "Why breastfeeding is part of this week''s story", "notes": "If you are breastfeeding, the US National Academies'' Recommended Dietary Allowance for carbohydrate is higher than it is for a non-pregnant woman — 210 g a day compared with 130 g. This reflects carbohydrate''s role in meeting the body''s glucose needs during lactation, including glucose used in producing lactose, the main carbohydrate in breast milk. It is a reference value that most mothers can meet through ordinary meals — not a target to chase or count gram by gram.", "breakfast_a": "Vegetable-and-paneer stuffed paratha with curd", "breakfast_b": "Masala omelette with whole-wheat toast and a slice of papaya", "lunch_a": "Khichdi (rice and moong dal) with a cucumber raita", "lunch_b": "Roti with mutton curry and a beetroot salad", "nourishment_break_a": "A glass of milk with roasted makhana", "nourishment_break_b": "Curd with a seasonal fruit", "dinner_a": "Rice, sambar, and a stir-fried vegetable", "dinner_b": "Rice with a fish curry and a cucumber salad", "still_hungry": "A small bowl of roasted chana"}, {"day_number": 3, "title": "Where it naturally shows up", "notes": "Rice, roti, millets like jowar and bajra, oats, fruit, milk, and legumes are all genuine carbohydrate sources — and between them, they already make up most of an ordinary Indian plate. You don''t need to add anything unusual; today is simply about noticing how naturally this nutrient already fits into what you eat, alongside protein and vegetables.", "breakfast_a": "Ragi dosa with a spiced sambar", "breakfast_b": "Vegetable-and-egg bhurji with whole-wheat toast", "lunch_a": "Jowar roti with a rajma curry and onion salad", "lunch_b": "Rice with mutton curry and a cabbage salad", "nourishment_break_a": "An apple with a small handful of walnuts", "nourishment_break_b": "Roasted chana with curd", "dinner_a": "Rice, a mixed-dal curry, and a beetroot-carrot salad", "dinner_b": "Vegetable pulao with a chicken curry", "still_hungry": "A glass of buttermilk"}, {"day_number": 4, "title": "About very-low-carbohydrate diets and breastfeeding", "notes": "Very-low-carbohydrate or ketogenic diets have not been adequately studied during lactation. Rare cases of lactation ketoacidosis have been reported, often when severe carbohydrate or calorie restriction occurred alongside skipped meals, illness, vomiting or other high energy demands. This does not mean that every moderately lower-carbohydrate meal is dangerous; it means that deliberate ketogenic dieting while breastfeeding should not be started without qualified clinical supervision. Severe restriction can make it harder to meet your overall energy and nutrient needs — that''s the real, well-supported concern, not a guaranteed drop in milk supply. Get help right away if: you are breastfeeding and develop persistent nausea or vomiting, abdominal pain, unusual breathlessness or rapid breathing, marked weakness, confusion or severe malaise — especially while fasting, eating very little, or following a ketogenic diet", "breakfast_a": "Oats porridge with milk and sliced banana", "breakfast_b": "Egg-and-vegetable omelette with whole-wheat toast", "lunch_a": "Rice, a bhindi (okra) and moong dal curry", "lunch_b": "Roti with a portion of grilled fish and a cucumber salad", "nourishment_break_a": "A boiled sweet potato with a small bowl of curd", "nourishment_break_b": "Roasted chana with a sliced pear or apple", "dinner_a": "Roti with a mixed-dal curry and a tomato-cucumber salad", "dinner_b": "Rice with a chicken stew and a stir-fried vegetable", "still_hungry": "A small bowl of curd with a banana"}, {"day_number": 5, "title": "When ordinary meals already cover it", "notes": "There is usually no need to track carbohydrate grams. When meals regularly include foods such as rice, roti, millet, oats, fruit, milk, curd, pulses or starchy vegetables, carbohydrate is already being supplied naturally across the day. The aim is not to push the amount higher, but to avoid unnecessary restriction and combine these foods with protein, vegetables, fruit or other nourishing accompaniments.", "breakfast_a": "Idli with sambar and coconut chutney", "breakfast_b": "Vegetable-and-egg uttapam with curd", "lunch_a": "Rice, a light dal curry, and a beetroot salad", "lunch_b": "Roti with mutton keema and a cucumber salad", "nourishment_break_a": "A mango or seasonal fruit bowl with a small bowl of curd", "nourishment_break_b": "A glass of milk with roasted chana", "dinner_a": "Vegetable khichdi with a cucumber raita", "dinner_b": "Rice with a chicken curry and a stir-fried vegetable", "still_hungry": "A handful of roasted chana with a date"}, {"day_number": 6, "title": "Away from home", "notes": "Meals eaten out or packed for travel are just as balanced as home meals when they combine a grain with protein and produce — a stuffed paratha with curd, a rice bowl, or idli-style foods all work well. Follow the usual food-safety guidance for anything perishable. Food safety: Curd, yogurt, and any dairy-topped item should be kept refrigerated or in an insulated bag with an ice pack until eaten, and eaten within about two hours if kept at room temperature — sooner in hot weather. Reheat any packed dinner until steaming hot before eating.", "breakfast_a": "Moong-dal and vegetable stuffed paratha with curd, kept cold", "breakfast_b": "Boiled egg with whole-wheat toast and a banana", "lunch_a": "Lemon-chana rice with mixed vegetables", "lunch_b": "Home-packed chicken-and-vegetable rice bowl", "nourishment_break_a": "A banana with a small handful of peanuts", "nourishment_break_b": "Unsweetened yogurt with fruit, kept cold", "dinner_a": "Reheated vegetable pulao with raita", "dinner_b": "Reheated mutton curry with rice and a cooked vegetable or salad", "still_hungry": "A glass of milk with a date"}, {"day_number": 7, "title": "Reflection", "notes": "No forced choices today — a chance to notice which combinations from this week actually worked for you. Still in Settling into strength. Carbohydrate turned out to be one of the most reassuring weeks in this series — the real story wasn''t about eating more of it, but about not cutting it too far, especially while breastfeeding.", "breakfast_a": "Whichever breakfast worked best for you this week", "breakfast_b": null, "lunch_a": "Whichever lunch you''d repeat", "lunch_b": null, "nourishment_break_a": "Whichever nourishment break suited you", "nourishment_break_b": null, "dinner_a": "Whichever dinner felt most manageable", "dinner_b": null, "still_hungry": "A familiar snack, if you''re still hungry"}]'::jsonb,
   'This week was mostly reassurance: did it help to know that your ordinary meals almost certainly already meet your carbohydrate needs, and that very-low-carbohydrate diets aren''t something to start on your own while breastfeeding?',
   'Next week continues this series'' walk through the nutrients that quietly hold everything else together.')
on conflict (stage, week_number) do update set
  trimester = excluded.trimester,
  phase_label = excluded.phase_label,
  theme_title = excluded.theme_title,
  mantra = excluded.mantra,
  why_it_matters = excluded.why_it_matters,
  condition_notes = excluded.condition_notes,
  meat_fish_eggs_note = excluded.meat_fish_eggs_note,
  using_meals_note = excluded.using_meals_note,
  days = excluded.days,
  reflection = excluded.reflection,
  looking_ahead = excluded.looking_ahead;

-- postpartum week 35: Dietary fat, the bigger picture behind omega-3 and omega-6
insert into nourish_week_content
  (stage, week_number, trimester, phase_label, theme_title, mantra,
   why_it_matters, condition_notes, meat_fish_eggs_note, using_meals_note,
   days, reflection, looking_ahead)
values
  ('postpartum',
   35,
   NULL,
   'Phase 4 of 6 — Settling into strength',
   'Dietary fat, the bigger picture behind omega-3 and omega-6',
   '"Fat supports energy, vitamin absorption and every cell in your body — the aim is adequacy and variety, not adding or eliminating it."',
   'Dietary fat does not need to be minimised or feared. How much you eat, and what kind, can vary — the amount that suits you is not the same for every mother. Fat is a concentrated source of energy, helps your body absorb vitamins A, D, E and K, and forms part of every cell membrane. The last two weeks in this series looked at two specific essential fats — omega-3 and omega-6. This week looks at the bigger picture: how much total fat your meals need, not just which kind. Reference ranges: ICMR-NIN places total fat within an Acceptable Macronutrient Distribution Range of 15-35% of daily energy for adults and 20-35% during pregnancy and lactation. The US National Academies use a comparable adult range of 20-35%. These are broad planning ranges — not gram targets or percentages that most mothers need to calculate at home. Visible and naturally occurring fat: Cooking oil, ghee and butter are sometimes called "visible fat." Fat also occurs naturally in foods such as nuts, seeds, milk, curd, paneer, eggs, fish and meat. Both contribute to total intake. Breastfeeding does not automatically require extra spoonfuls of oil or ghee; a varied diet can provide fat through both sources. A common belief, gently corrected: Eating extra ghee, butter or oil does not reliably increase milk volume. The kinds of fat in a mother''s diet can influence parts of the fatty-acid profile of breast milk, but simply adding more fat does not automatically make milk "better" or more nourishing. Milk supply still depends most directly on frequent and effective milk removal. A note on fat quality: Not all fat needs the same amount of attention. Oils such as sunflower, groundnut, or mustard, along with nuts, seeds, and fish, provide unsaturated fat and were already covered for their omega-3 and omega-6 content in the last two weeks. Ghee, butter, coconut, red meat, and fried food are more concentrated in saturated fat — worth enjoying in ordinary amounts rather than either avoiding entirely or relying on heavily every day. Every day below offers two distinct, individually balanced meals for each slot — pick whichever fits your day, your preferences, or what''s in your kitchen. If you have a diagnosed food allergy: If you have any diagnosed food allergy — including an allergy to egg, dairy, wheat, soy, peanut, tree nuts, seeds, fish or shellfish — avoid that food completely and choose an alternative you already tolerate. Do not trial a problem food to pursue this week''s nutrient. Do not automatically substitute seeds for nuts unless the seed is already known to be tolerated. If you are managing a health condition - If you have diabetes or a recent history of gestational diabetes: fat does not raise blood glucose in the same immediate way as carbohydrate, but that does not make added fat a "free food." Overall meal composition, portion size and the type of fat still matter. Follow your prescribed meal plan and postpartum glucose-testing advice if you have them. - If you have high blood pressure or other cardiovascular risk factors: the type of fat you eat matters more than trying to eliminate fat altogether. Favouring unsaturated oils over excess ghee, butter, or fried food is a reasonable general approach — ask your care team if you need more specific guidance. - If you have gallbladder disease, a history of pancreatitis, or any condition affecting fat digestion: fat intake may need individual adjustment. Follow your care team''s specific guidance rather than this general chart. - If you have a thyroid condition or PCOS: nothing about this week''s guidance changes specifically for you — continue your usual balanced diet and any care-team guidance already in place.',
   NULL,
   NULL,
   NULL,
   '[{"day_number": 1, "title": "Anchor", "notes": "Fat has quietly been part of almost every meal in this series — in the oil a dish is cooked in, the fat naturally present in milk, nuts, and meat. Today is about noticing it''s already there, alongside protein, carbohydrate, and vegetables or fruit — not about adding more.", "breakfast_a": "Vegetable upma with peanuts and curd", "breakfast_b": "Egg-and-vegetable appam with a side of fruit", "lunch_a": "Chole and vegetable stuffed roti roll with a cucumber salad", "lunch_b": "Chicken-and-vegetable millet pulao", "nourishment_break_a": "A small handful of walnuts with a seasonal fruit", "nourishment_break_b": "Curd with roasted flaxseed", "dinner_a": "Mixed-millet, chickpea and vegetable bowl with a light ghee tempering and curd", "dinner_b": "Mutton keema with peas and jowar roti", "still_hungry": "A small bowl of curd with a few peanuts"}, {"day_number": 2, "title": "Why adequacy matters during breastfeeding", "notes": "Breastfeeding increases overall energy needs and the need for essential fatty acids, but most mothers do not need to calculate a particular percentage of energy from fat. Ordinary meals containing some oil alongside foods such as dairy, nuts, seeds, eggs, fish, meat, pulses or soy can provide adequate fat without counting percentages or deliberately adding extra spoonfuls.", "breakfast_a": "Vegetable dosa with sambar", "breakfast_b": "Boiled egg with whole-wheat toast, roasted peanuts, and a sliced fruit", "lunch_a": "Bajra roti with a mixed-bean curry and a cucumber salad", "lunch_b": "Fish with lemon rice and cooked vegetables", "nourishment_break_a": "A glass of milk with a small handful of almonds", "nourishment_break_b": "Roasted chana with a seasonal fruit", "dinner_a": "Rice, a drumstick sambar, and a stir-fried vegetable", "dinner_b": "Chicken-and-vegetable jowar wrap with a side of curd", "still_hungry": "Roasted chana with a piece of fruit"}, {"day_number": 3, "title": "Where it naturally shows up", "notes": "Oil, ghee, butter, milk, curd, nuts, seeds, meat, fish, and eggs all contribute fat — between them, they already make up much of an ordinary Indian diet. You don''t need to add anything unusual; today is simply about noticing how naturally this nutrient already fits into what you eat.", "breakfast_a": "Peanut-and-vegetable poha", "breakfast_b": "Egg curry with steamed rice and a stir-fried vegetable", "lunch_a": "Chole and vegetable tikki bowl with curd", "lunch_b": "Roti with a chicken curry and a sautéed vegetable", "nourishment_break_a": "A pear with a small handful of pistachios", "nourishment_break_b": "Curd with a spoon of roasted sesame seeds", "dinner_a": "Multigrain roti with a lauki (bottle gourd) and chana dal curry", "dinner_b": "Mutton keema-stuffed roti with cucumber raita", "still_hungry": "A small bowl of curd with a date"}, {"day_number": 4, "title": "About very-low-fat diets and breastfeeding", "notes": "Very-low-fat diets can make nutritional adequacy harder during breastfeeding. Fat is needed to absorb vitamins A, D, E and K, and it''s a concentrated energy source at a time when your body''s energy needs are already higher. This isn''t a reason to add extra fat on purpose — it''s a reason not to cut it drastically, especially without guidance from your care team.", "breakfast_a": "Vegetable dalia (broken wheat porridge) with crushed peanuts", "breakfast_b": "Egg paratha with curd", "lunch_a": "Savoury oats with peas and curd", "lunch_b": "Roti with a portion of pan-seared fish and a stir-fried vegetable", "nourishment_break_a": "A guava with a small handful of pumpkin seeds", "nourishment_break_b": "A glass of buttermilk with roasted chana", "dinner_a": "Tofu-and-vegetable bhurji with roti", "dinner_b": "Paneer-and-vegetable rice bowl", "still_hungry": "A small bowl of curd with a few dates"}, {"day_number": 5, "title": "The quality question, gently", "notes": "Not all fat needs the same amount of attention. Oils such as sunflower, groundnut, or mustard, along with nuts, seeds, and fish, provide unsaturated fat and were already covered for their omega-3 and omega-6 content in the last two weeks. Ghee, butter, coconut, red meat, and fried food are more concentrated in saturated fat — worth enjoying in ordinary amounts rather than either avoiding entirely or relying on heavily every day.", "breakfast_a": "Moong dal cheela with a tomato chutney", "breakfast_b": "Chicken sandwich with a side of fruit", "lunch_a": "Rice, a palak (spinach) and chana dal curry, and a carrot salad", "lunch_b": "Roti with a fish curry and a cucumber salad", "nourishment_break_a": "A banana with a small handful of almonds", "nourishment_break_b": "Curd with a spoon of chia or flaxseed", "dinner_a": "Vegetable uttapam with sambar", "dinner_b": "Egg-and-vegetable dosa roll", "still_hungry": "A glass of milk with roasted peanuts"}, {"day_number": 6, "title": "Away from home", "notes": "Meals eaten out or packed for travel are just as balanced as home meals when they combine a grain with protein, produce, and an ordinary amount of fat — a stuffed roll with curd, a rice bowl, or dosa-style foods all work well. Follow the usual food-safety guidance for anything perishable. Food safety: Paneer, curd, and any dairy-based item should be kept refrigerated or in an insulated bag with an ice pack until eaten, and eaten within about two hours at room temperature — sooner in hot weather. Reheat any packed dinner until steaming hot before eating.", "breakfast_a": "Paneer-and-vegetable stuffed roti roll, packed warm", "breakfast_b": "Egg-and-vegetable bhurji wrapped in a chapati, packed warm", "lunch_a": "Vegetable pulao with roasted peanuts and curd", "lunch_b": "Home-packed mutton curry with rice and a cooked vegetable or salad", "nourishment_break_a": "Roasted chana with an orange", "nourishment_break_b": "A small bowl of curd with fruit", "dinner_a": "Reheated paneer-and-vegetable curry with rice", "dinner_b": "Reheated chicken-and-vegetable jowar wrap", "still_hungry": "A glass of buttermilk with a date"}, {"day_number": 7, "title": "Reflection", "notes": "No forced choices today — a chance to notice which combinations from this week actually worked for you. Still in Settling into strength. Total dietary fat turned out to be a reassuring close to the two essential-fat weeks earlier in this series — the real story was about adequacy and variety, not adding more or restricting it, especially while breastfeeding.", "breakfast_a": "Whichever breakfast worked best for you this week", "breakfast_b": null, "lunch_a": "Whichever lunch you''d repeat", "lunch_b": null, "nourishment_break_a": "Whichever nourishment break suited you", "nourishment_break_b": null, "dinner_a": "Whichever dinner felt most manageable", "dinner_b": null, "still_hungry": "A familiar snack, if you''re still hungry"}]'::jsonb,
   'This week was mostly reassurance: did it help to know that fat is already part of your ordinary meals, and that adequacy — not adding more — is what actually matters, especially while breastfeeding?',
   'Next week continues this series'' walk through the nutrients that quietly hold everything else together.')
on conflict (stage, week_number) do update set
  trimester = excluded.trimester,
