  looking_ahead = excluded.looking_ahead;

-- postpartum week 36: Antioxidants, the case for a colourful plate
insert into nourish_week_content
  (stage, week_number, trimester, phase_label, theme_title, mantra,
   why_it_matters, condition_notes, meat_fish_eggs_note, using_meals_note,
   days, reflection, looking_ahead)
values
  ('postpartum',
   36,
   NULL,
   'Phase 4 of 6 — Settling into strength',
   'Antioxidants, the case for a colourful plate',
   '"Not one nutrient this time — colour and variety on your plate, more than any single number."',
   'Antioxidants aren''t one nutrient to chase — they''re a case for variety. A colourful, varied plate does more than any single vitamin on its own. This series has already covered several individual antioxidant nutrients on their own — vitamin C, vitamin E, zinc, selenium. This week steps back to look at the bigger picture: eating a genuinely varied, colourful mix of fruits and vegetables brings together antioxidant vitamins and plant compounds in a way no single nutrient can on its own. Reference guidance: ICMR-NIN''s 2024 "My Plate for the Day" model for a 2000-kcal diet includes approximately 400 g of vegetables and 100 g of fresh fruit. WHO advises adults to consume at least 400 g of fruit and vegetables combined each day, excluding potatoes and other starchy roots. These are population-level planning guides — not amounts every mother needs to weigh or reproduce exactly. In practice: Vegetables can appear across the main meals, with fresh fruit once or twice during the day. The exact amount and combination can vary with appetite, energy needs, affordability, availability and any individual medical advice. What polyphenols and flavonoids are: Polyphenols and flavonoids are plant compounds found in colourful fruits, vegetables, tea, and spices. Unlike vitamin C or iron, they don''t have an official recommended daily amount — they aren''t considered essential for survival — but a varied, colourful diet is a reasonable, evidence-based way to include them. A note on supplements: Antioxidant supplements such as extra vitamin C, vitamin E or beta-carotene have not been shown to reproduce all the benefits associated with a varied diet or to prevent chronic disease reliably in generally healthy adults. Whole foods are the better-supported way to obtain a varied mixture of antioxidant nutrients and plant compounds. This does not mean stopping iron, vitamin D, B12, a postnatal multivitamin, or any supplement prescribed for a diagnosed need — continue those according to your care team''s advice. Every day below offers two distinct, individually balanced meals for each slot — pick whichever fits your day, your preferences, or what''s in your kitchen. If you have a diagnosed food allergy: If you have any diagnosed food allergy — including an allergy to egg, dairy, wheat, soy, peanut, tree nuts, seeds, fish or shellfish — avoid that food completely and choose an alternative you already tolerate. Do not trial a problem food to pursue this week''s nutrient. Do not automatically substitute seeds for nuts unless the seed is already known to be tolerated. If you are managing a health condition - If you have diabetes or a recent history of gestational diabetes: whole fruit still counts toward this week''s goal, but portion and type matter for blood glucose — favour whole fruit over juice, and pair it with protein or fat where you can. Follow your prescribed meal plan if you have one. - If you have kidney disease or have been told to watch your potassium: some fruits and vegetables — such as bananas, oranges, potatoes, and tomatoes — are higher in potassium and may need to be limited. Follow your care team''s specific guidance rather than this general chart. - If you have a thyroid condition, high blood pressure, or PCOS: nothing about this week''s guidance changes specifically for you — continue your usual balanced diet and any care-team guidance already in place.',
   NULL,
   NULL,
   NULL,
   '[{"day_number": 1, "title": "Anchor", "notes": "Fruits and vegetables have been part of nearly every meal in this series — but this week is about noticing them as their own thing: how much, and how many different colours, are actually on your plate day to day.", "breakfast_a": "Vegetable and spinach paratha with curd", "breakfast_b": "Egg and bell pepper omelette with whole-wheat toast", "lunch_a": "Rice, a mixed-vegetable curry (carrot, beans, peas), a bowl of dal, and a beetroot salad", "lunch_b": "Roti with chicken curry and a tomato-cucumber salad", "nourishment_break_a": "A bowl of papaya and orange segments with a small handful of roasted chana", "nourishment_break_b": "A small bowl of pomegranate with curd", "dinner_a": "Roti with a pumpkin and chana dal curry", "dinner_b": "Rice with a fish curry and a stir-fried okra", "still_hungry": "A small bowl of mixed fruit with curd"}, {"day_number": 2, "title": "Why colour, not just quantity", "notes": "Colour is a practical reminder — not a scorecard. Green, orange, red and purple produce can contribute different nutrients and plant compounds, but pale foods such as cabbage, cauliflower, onion, garlic and bottle gourd still count. You do not need every colour at every meal or even every day; variety across the week is enough.", "breakfast_a": "Beetroot and carrot paratha with curd", "breakfast_b": "Boiled egg with whole-wheat toast and a sliced orange", "lunch_a": "Rice, a rajma curry, and a cabbage-carrot salad", "lunch_b": "Roti with mutton curry and a spinach sabzi", "nourishment_break_a": "A guava with a small handful of peanuts", "nourishment_break_b": "A bowl of grapes with curd", "dinner_a": "Rice, a mixed-dal curry, and a sautéed capsicum (bell pepper) sabzi", "dinner_b": "Roti with chicken curry and a beetroot salad", "still_hungry": "A small bowl of papaya with curd or a small handful of roasted chana"}, {"day_number": 3, "title": "Where it naturally shows up", "notes": "Seasonal, local produce is the easiest way to get real variety — spinach, methi, carrots, beetroot, pumpkin, gourds, citrus fruits, papaya, guava, and pomegranate are common options in many parts of India. Availability and price vary by region and season, so choose the fruits and vegetables that are affordable and familiar where you live.", "breakfast_a": "Spinach-corn besan chilla with curd", "breakfast_b": "Egg-and-spinach millet bowl", "lunch_a": "Palak chole with rice and a carrot-cucumber salad", "lunch_b": "Chicken and bell-pepper rice bowl", "nourishment_break_a": "A sliced apple with a small handful of walnuts", "nourishment_break_b": "A glass of buttermilk with a small handful of pumpkin seeds", "dinner_a": "Multigrain roti with a chana dal curry and a beetroot raita", "dinner_b": "Rice with a fish and pumpkin curry", "still_hungry": "A bowl of watermelon or muskmelon with a small handful of tolerated nuts or seeds"}, {"day_number": 4, "title": "About antioxidant supplements", "notes": "Antioxidant supplements such as extra vitamin C, vitamin E or beta-carotene have not been shown to reproduce all the benefits associated with a varied diet or to prevent chronic disease reliably in generally healthy adults. Whole foods are the better-supported way to obtain a varied mixture of antioxidant nutrients and plant compounds. This does not mean stopping iron, vitamin D, B12, a postnatal multivitamin, or any supplement prescribed for a diagnosed need — continue those according to your care team''s advice.", "breakfast_a": "Beans-and-peas poha with curd", "breakfast_b": "Pumpkin-paneer bhurji with jowar roti", "lunch_a": "Rice, a mixed-vegetable and moong dal curry, and a cucumber-tomato salad", "lunch_b": "Chicken keema with peas and capsicum, served with roti", "nourishment_break_a": "A bowl of orange segments with a small handful of roasted chana", "nourishment_break_b": "A glass of buttermilk with a small handful of roasted peanuts", "dinner_a": "Vegetable handvo with a coriander chutney", "dinner_b": "Rice with an egg curry and a stir-fried vegetable", "still_hungry": "A small bowl of curd with a few dates"}, {"day_number": 5, "title": "When ordinary meals already cover it", "notes": "There is no need to weigh produce or make every meal perfectly colourful. Regularly including vegetables in main meals and fresh fruit during the day builds variety naturally. Some days will contain more and others less; the overall pattern matters more than reaching an exact number every day.", "breakfast_a": "Vegetable idli with tomato chutney and sambar", "breakfast_b": "Egg-and-vegetable bhurji with whole-wheat toast", "lunch_a": "Rice, a mixed-vegetable sambar, and a carrot salad", "lunch_b": "Roti with a fish curry and a stir-fried vegetable", "nourishment_break_a": "A sliced pear with a small handful of almonds", "nourishment_break_b": "A small bowl of curd with a spoon of chia seeds", "dinner_a": "Cabbage-peas paratha with curd", "dinner_b": "Rice with a chicken curry and a cabbage sabzi", "still_hungry": "A glass of milk with a few dates"}, {"day_number": 6, "title": "Away from home", "notes": "Meals eaten out or packed for travel can still include real variety — a vegetable-forward roll, a fruit chaat, or a simple dal-rice with a salad on the side all count. Follow the usual food-safety guidance for anything perishable. Food safety: Paneer, curd, and any dairy-based item should be kept refrigerated or in an insulated bag with an ice pack until eaten, and eaten within about two hours at room temperature — sooner in hot weather. If carrying cooked egg, paneer, meat or another perishable hot food for later, keep it properly hot in a suitable insulated container or properly chilled with an ice pack — do not leave it merely warm for several hours. Reheat any packed dinner until steaming hot before eating.", "breakfast_a": "Beetroot-paneer paratha, prepared fresh and eaten promptly", "breakfast_b": "Egg-and-spinach cheela, prepared fresh and eaten promptly", "lunch_a": "Cauliflower-peas pulao with roasted peanuts and curd", "lunch_b": "Home-packed mutton keema with peas and cabbage, served with rice", "nourishment_break_a": "A fruit chaat (mixed seasonal fruit with a squeeze of lemon) with a small handful of roasted chana", "nourishment_break_b": "A small bowl of curd with a spoon of roasted seeds", "dinner_a": "Reheated mixed-vegetable curry with rice and a bowl of dal", "dinner_b": "Reheated chicken-and-vegetable curry with rice", "still_hungry": "A glass of buttermilk with a date"}, {"day_number": 7, "title": "Reflection", "notes": "No forced choices today — a chance to notice which combinations from this week actually worked for you. Still in Settling into strength. This week wasn''t about one nutrient, but about noticing how much colour and variety already sits on your plate — and how easy it is to add a little more without overhauling anything.", "breakfast_a": "Whichever breakfast worked best for you this week", "breakfast_b": null, "lunch_a": "Whichever lunch you''d repeat", "lunch_b": null, "nourishment_break_a": "Whichever nourishment break suited you", "nourishment_break_b": null, "dinner_a": "Whichever dinner felt most manageable", "dinner_b": null, "still_hungry": "A familiar snack, if you''re still hungry"}]'::jsonb,
   'This week was mostly about noticing: did it help to see how much of this already happens naturally, and how variety — not one single food — is what actually matters?',
   'Next week continues this series'' walk through the nutrients that quietly hold everything else together.')
on conflict (stage, week_number) do update set
  trimester = excluded.trimester,
  phase_label = excluded.phase_label,
  theme_title = excluded.theme_title,
  mantra = excluded.mantra,
  why_it_matters = excluded.why_it_matters,
  condition_notes = excluded.condition_notes,
  meat_fish_eggs_note = excluded.meat_fish_eggs_note,
  using_meals_note = excluded.using_meals_note,
  days = excluded.days,
  reflection = excluded.reflection,
  looking_ahead = excluded.looking_ahead;

-- postpartum week 37: Chloride, quietly supporting fluid balance and digestion
insert into nourish_week_content
  (stage, week_number, trimester, phase_label, theme_title, mantra,
   why_it_matters, condition_notes, meat_fish_eggs_note, using_meals_note,
   days, reflection, looking_ahead)
values
  ('postpartum',
   37,
   NULL,
   'Phase 4 of 6 — Settling into strength',
   'Chloride, quietly supporting fluid balance and digestion',
   '"Ordinary salt already supplies this — the real story here is digestion, not another number to track."',
   'Chloride deficiency from diet alone is uncommon because salt and many prepared foods contain sodium chloride. This does not mean adding extra salt: continue following this programme''s salt-moderation guidance and any individual advice for blood pressure, kidney disease or fluid retention. Chloride is the main negatively charged mineral in the fluid outside your cells, where it works with sodium in fluid and acid–base balance. It also forms part of hydrochloric acid in the stomach. Stomach acid helps digest food, release vitamin B12 from food proteins and support the absorption of non-haem iron. Reference guidance: ICMR-NIN''s 2020 summary does not provide a separate chloride reference value. The US National Academies set an Adequate Intake of 2.3 g a day for younger adults, including during pregnancy and lactation. This is based on chloride accompanying sodium in equal molecular amounts in ordinary salt — not equal gram amounts. Because everyday food and seasoning usually provide chloride readily, this is background information, not a reason to calculate chloride or add more salt. Where it comes from: Most dietary chloride comes from sodium chloride added during cooking or present in packaged, restaurant and other prepared foods. Smaller amounts occur naturally in foods such as milk, eggs, meat and some vegetables. Because salt is already widespread in ordinary diets, chloride generally does not need to be pursued separately. Every day below offers two distinct, individually balanced meals for each slot — pick whichever fits your day, your preferences, or what''s in your kitchen. If you have a diagnosed food allergy: If you have any diagnosed food allergy — including an allergy to egg, dairy, wheat, soy, peanut, tree nuts, seeds, fish or shellfish — avoid that food completely and choose an alternative you already tolerate. Do not trial a problem food to pursue this week''s nutrient. Do not automatically substitute seeds for nuts unless the seed is already known to be tolerated. If you are managing a health condition - If you have kidney disease or a condition needing fluid or electrolyte restriction: chloride is managed together with sodium and potassium as part of your overall fluid and electrolyte plan. Follow your care team''s specific guidance rather than this general chart. - If you have high blood pressure: nothing extra is needed for chloride specifically — the general salt-moderation guidance from earlier in this series already covers it, since ordinary salt supplies sodium and chloride together. - If you have persistent vomiting or diarrhea: these can cause a genuine loss of water, chloride, sodium and potassium. Seek prompt medical help if you cannot keep fluids down, pass very little urine, feel faint or confused, or notice other warning signs — see Day 4 for full guidance, including on oral rehydration solution (ORS).',
   NULL,
   NULL,
   NULL,
   '[{"day_number": 1, "title": "What chloride is, and why no extra is needed", "notes": "This week''s mineral, chloride, is one you almost never need to think about directly — it travels alongside sodium in ordinary salt, and salt is already part of nearly every Indian meal. The story here is understanding what chloride does, not adding more of it.", "breakfast_a": "Vegetable suji chilla with curd", "breakfast_b": "Egg-and-vegetable rice pancakes", "lunch_a": "Rice, a moong dal curry, and a sautéed beans sabzi", "lunch_b": "Jowar roti with chicken saag", "nourishment_break_a": "A pear with a small handful of walnuts", "nourishment_break_b": "A glass of buttermilk with a small handful of roasted makhana (fox nuts)", "dinner_a": "Dal dhokli with vegetables", "dinner_b": "Rice with a fish curry and a sautéed capsicum", "still_hungry": "A small bowl of curd with a few dates"}, {"day_number": 2, "title": "Sodium and chloride travel together — but are not the same mineral", "notes": "Sodium and chloride have separate functions and separate reference values. In ordinary diets, however, most of both minerals arrive together as sodium chloride, so chloride rarely requires separate food planning. This does not mean that more salt is beneficial.", "breakfast_a": "Masala oats idli with sambar", "breakfast_b": "Egg-and-peas pulao with cucumber", "lunch_a": "Vegetable barley khichdi with curd", "lunch_b": "Mutton-and-vegetable jowar bowl", "nourishment_break_a": "A guava with a small handful of pistachios", "nourishment_break_b": "A bowl of pomegranate with curd", "dinner_a": "Vegetable kadhi with bajra roti", "dinner_b": "Chicken-and-vegetable dosa roll", "still_hungry": "A glass of milk with a date"}, {"day_number": 3, "title": "Stomach acid, B12 release, and non-haem iron", "notes": "Chloride is the main negatively charged mineral in the fluid outside your cells, where it works with sodium in fluid and acid–base balance. It also forms part of hydrochloric acid in the stomach. Stomach acid helps digest food, release vitamin B12 from food proteins and support the absorption of non-haem iron.", "breakfast_a": "Sweet-potato and paneer tikki with curd", "breakfast_b": "Adai-style mixed-dal dosa with chutney", "lunch_a": "Kala-chana and millet bowl with a cucumber salad", "lunch_b": "Fish tikka with vegetable daliya", "nourishment_break_a": "A sliced apple with a small handful of almonds", "nourishment_break_b": "A glass of buttermilk with a small handful of roasted sesame seeds", "dinner_a": "Multigrain roti with a beans and moong dal curry", "dinner_b": "Jowar roti with a chicken-and-methi (fenugreek) curry", "still_hungry": "A small bowl of mixed fruit with curd"}, {"day_number": 4, "title": "Losses through vomiting or diarrhoea, and correct ORS guidance", "notes": "Vomiting and diarrhoea can cause loss of water, chloride, sodium and potassium. If you can drink, take frequent small sips of safe fluid. A properly prepared oral rehydration solution replaces water and electrolytes in tested proportions; coconut water, juice or extra salt added to food is not an equivalent substitute. Prepare ORS exactly according to the packet instructions — do not make it stronger or weaker. Continue breastfeeding if applicable and tolerated. If you are actively vomiting or have significant diarrhoea, pause the ordinary chart and prioritise fluids, ORS where appropriate, tolerated food and clinical guidance. The options below are only for when symptoms are mild or improving and food is staying down. Choose whatever feels tolerable; you do not need to complete the chart while unwell. Keep recovering-day preparations lightly spiced and not oily; individual tolerance matters more than following the listed meal. Get help right away if: you cannot keep fluids down, pass very little urine, feel faint or confused, have severe weakness, blood in the stool or stool that is black and tarry, high fever, severe abdominal pain, marked thirst or worsening diarrhoea Also tell your care team if: symptoms are not improving within 24–48 hours, or earlier if you have kidney disease, diabetes or another condition affecting fluid balance", "breakfast_a": "Curd rice with a tempering of curry leaves and mustard seeds", "breakfast_b": "Plain soft khichdi, with a little ghee only if tolerated", "lunch_a": "Rice, a mixed-vegetable sambar, and a sautéed beans sabzi", "lunch_b": "Roti with a mild, lightly spiced chicken curry and a stir-fried pumpkin", "nourishment_break_a": "A ripe banana with a small handful of roasted chana, if tolerated", "nourishment_break_b": "Plain curd with soft rice, if tolerated", "dinner_a": "Soft khichdi, with a little ghee only if tolerated, and a cucumber raita", "dinner_b": "Rice with a mild, lightly spiced fish curry and a stir-fried spinach", "still_hungry": "A glass of buttermilk with a pinch of roasted cumin, if tolerated"}, {"day_number": 5, "title": "Hidden salt in packaged, restaurant, and pickle-heavy meals", "notes": "There is no need to count chloride grams or deliberately increase salt — chloride deficiency from diet alone is uncommon because salt and many prepared foods already contain sodium chloride. Continue following this programme''s salt-moderation guidance and any individual advice for blood pressure, kidney disease or fluid retention. Packaged snacks, restaurant food, pickles, papad, and salted namkeen are often much higher in salt than home-cooked meals — worth noticing, not something to avoid entirely.", "breakfast_a": "Rava (semolina) idli with sambar", "breakfast_b": "Chicken-and-vegetable sandwich", "lunch_a": "Rice, a palak (spinach) dal, and a cucumber-tomato salad", "lunch_b": "Soy-peas pulao with cucumber raita", "nourishment_break_a": "A sliced pear with a small handful of cashews", "nourishment_break_b": "A small bowl of curd with a spoon of roasted flaxseed", "dinner_a": "Lauki kofta with roti", "dinner_b": "Rice with a mutton curry and a beetroot salad", "still_hungry": "A glass of milk with a few dates"}, {"day_number": 6, "title": "Away from home, without adding extra salt", "notes": "Meals eaten out or packed for travel already contain plenty of salt through their own seasoning — there''s no need to add more. If restaurant or packaged food tastes noticeably salty, that''s often true regardless of what this week''s chart says; balance it out with simpler, home-cooked meals around it rather than trying to compensate in the moment. Follow the usual food-safety guidance for anything perishable. Food safety: Paneer, curd, and any dairy-based item should be kept refrigerated or in an insulated bag with an ice pack until eaten, and eaten within about two hours at room temperature — sooner in hot weather. If carrying cooked egg, paneer, meat or another perishable food for later, keep it properly hot in a suitable insulated container or properly chilled with an ice pack — do not leave it merely warm for several hours. Reheat any packed dinner until steaming hot before eating.", "breakfast_a": "Paneer-and-peas suji upma, prepared fresh and eaten promptly", "breakfast_b": "Egg-and-vegetable roll, prepared fresh and eaten promptly", "lunch_a": "Chana-and-spinach stuffed roti with curd", "lunch_b": "Home-packed chicken-and-vegetable curry with rice", "nourishment_break_a": "Fruit chaat with roasted chana or a small portion of tolerated nuts", "nourishment_break_b": "A small bowl of curd with roasted chana", "dinner_a": "Reheated palak (spinach) and chana dal curry with rice", "dinner_b": "Reheated mutton keema with vegetables, served with rice", "still_hungry": "A glass of buttermilk with a date"}, {"day_number": 7, "title": "Reflection", "notes": "No forced choices today — a chance to notice which combinations from this week actually worked for you. Still in Settling into strength. This week''s mineral turned out to be one you almost never need to think about directly — the real story was what it quietly does for digestion, and how sodium and chloride travel together without being the same thing.", "breakfast_a": "Whichever breakfast worked best for you this week", "breakfast_b": null, "lunch_a": "Whichever lunch you''d repeat", "lunch_b": null, "nourishment_break_a": "Whichever nourishment break suited you", "nourishment_break_b": null, "dinner_a": "Whichever dinner felt most manageable", "dinner_b": null, "still_hungry": "A familiar snack, if you''re still hungry"}]'::jsonb,
   'This week was mostly about noticing: did it help to see how something already fully covered by ordinary cooking still has a real, distinct job in your body?',
   'Next week continues this series'' walk through the nutrients that quietly hold everything else together.')
on conflict (stage, week_number) do update set
  trimester = excluded.trimester,
  phase_label = excluded.phase_label,
  theme_title = excluded.theme_title,
  mantra = excluded.mantra,
  why_it_matters = excluded.why_it_matters,
