  meat_fish_eggs_note = excluded.meat_fish_eggs_note,
  using_meals_note = excluded.using_meals_note,
  days = excluded.days,
  reflection = excluded.reflection,
  looking_ahead = excluded.looking_ahead;

-- postpartum week 38: Fluoride, a nutrient your water carries more than your food
insert into nourish_week_content
  (stage, week_number, trimester, phase_label, theme_title, mantra,
   why_it_matters, condition_notes, meat_fish_eggs_note, using_meals_note,
   days, reflection, looking_ahead)
values
  ('postpartum',
   38,
   NULL,
   'Phase 4 of 6 — Settling into strength',
   'Fluoride, a nutrient your water carries more than your food',
   '"This week''s mineral barely changes for pregnancy or breastfeeding — the real story is your water, not your plate."',
   'Fluoride is different from most minerals in this programme. Its best-established benefit is preventing tooth decay, and much of that protection comes from fluoride contacting the teeth through toothpaste or appropriately fluoridated water. This is not a mineral to pursue through particular meals or supplements. Fluoride''s best-established role is protecting teeth: it slows the breakdown of tooth mineral by acids from plaque bacteria and helps rebuild (remineralise) tooth surfaces in the earliest stages of decay. It is also taken up by bone tissue, though unlike its role in dental health, using fluoride specifically to strengthen bone is not part of routine care. Reference guidance: ICMR-NIN''s 2020 summary does not include a separate fluoride reference value. The US National Academies set an Adequate Intake for adult women of 3 mg a day — and unlike most nutrients in this series, this figure does not increase during pregnancy or breastfeeding. A Tolerable Upper Intake Level of 10 mg a day, from all sources combined, has also been set for adults, including during pregnancy and lactation. Worth knowing: These are US dietary reference values derived around dental-caries prevention — they are not targets to reach using toothpaste, tea or fluoride supplements, and the 10 mg UL is not a desirable intake goal. Do not start a fluoride dietary supplement unless it has been specifically recommended after considering your water source and dental needs. Swallowed and topical sources: Fluoride that is swallowed comes mainly from drinking water and foods or beverages prepared with that water; brewed tea can also contribute appreciable amounts. Fluoride toothpaste works mainly by contacting the tooth surface and should be spat out rather than swallowed. These are different routes of exposure and should not be treated as interchangeable ways of reaching a number. Every day below offers two distinct, individually balanced meals for each slot — pick whichever fits your day, your preferences, or what''s in your kitchen. If you have a diagnosed food allergy: If you have any diagnosed food allergy — including an allergy to egg, dairy, wheat, soy, peanut, tree nuts, seeds, fish or shellfish — avoid that food completely and choose an alternative you already tolerate. Do not trial a problem food to pursue this week''s nutrient. Do not automatically substitute seeds for nuts unless the seed is already known to be tolerated. If you are managing a health condition - If you have significant kidney disease or reduced kidney function: fluoride is cleared largely through urine, so impaired kidney function may reduce clearance and increase retention. Do not start a fluoride-containing dietary supplement unless your clinician or dentist recommends it. Routine fluoride toothpaste, when used as directed and spat out, should not be stopped solely for this reason; ask your kidney and dental teams if you have concerns about high-fluoride water or specialised fluoride treatments. - If your household''s drinking water comes from a private borewell, hand pump, or another source you haven''t had tested: check the actual fluoride result for that specific source through your local water-supply authority, panchayat, or a recognised laboratory — safe and unsafe sources can exist close together, so a state or region alone doesn''t tell you enough. See Day 4 for more detail.',
   NULL,
   NULL,
   NULL,
   '[{"day_number": 1, "title": "What fluoride is, and why the target barely moves", "notes": "This week''s mineral, fluoride, is one you''re unlikely to think about through food at all. Most swallowed fluoride comes from drinking water and foods or drinks prepared with that water—not from particular foods on your plate. Fluoride toothpaste provides additional protection mainly through direct contact with the teeth and should be spat out rather than swallowed. Unlike almost every other nutrient in this series, the reference amount for fluoride does not increase during pregnancy or breastfeeding.", "breakfast_a": "Kanda-batata poha with sprouts and curd", "breakfast_b": "Egg bhurji with whole-wheat toast and tomato", "lunch_a": "Rice, a horse-gram (kulthi) dal, and a lauki (bottle gourd) sabzi", "lunch_b": "Phulka with chicken sukka and a cucumber salad", "nourishment_break_a": "A sliced banana with a small handful of walnuts", "nourishment_break_b": "A glass of buttermilk with a small handful of roasted chana", "dinner_a": "Multigrain roti with chana dal curry and a seasonal vegetable sabzi", "dinner_b": "Fish-and-vegetable jowar bowl", "still_hungry": "A small bowl of curd with a few raisins"}, {"day_number": 2, "title": "Where it naturally comes from — mostly water, not food", "notes": "Fluoride occurs naturally in soil and water, and only in trace amounts in most foods — well under a tenth of a milligram in a typical serving. Brewed tea is the one real exception, picking up meaningfully more fluoride from the plant and the water used to brew it. This is not a reason to drink tea specifically for fluoride. If you already drink tea, simply include it within your usual caffeine limit.", "breakfast_a": "Mixed-dal paniyaram with coconut chutney", "breakfast_b": "Egg-and-tomato paratha", "lunch_a": "Rice, a matar (green pea) curry, and a cucumber-tomato salad", "lunch_b": "Jowar roti with mutton curry, a sautéed beans sabzi, and curd", "nourishment_break_a": "A wedge of pineapple with a small handful of pistachios", "nourishment_break_b": "A bowl of chikoo (sapota) with curd", "dinner_a": "Vegetable-and-moong-dal dalia khichdi", "dinner_b": "Roti with a chicken curry and a stir-fried beans sabzi", "still_hungry": "A glass of milk with a few almonds"}, {"day_number": 3, "title": "Why breastfeeding doesn''t ask for more", "notes": "Fluoride concentrations in breast milk are very low, even when maternal fluoride exposure is higher. Accordingly, the adult-woman reference value remains 3 mg during lactation rather than increasing. This is not a reason for a breastfeeding mother to take fluoride supplements for her baby''s teeth; infant fluoride decisions should be based on age, tooth eruption, water source and professional dental guidance.", "breakfast_a": "Vegetable and lentil appe with sambar", "breakfast_b": "Idiyappam served with a fully cooked egg-and-vegetable curry", "lunch_a": "Rice, a lobia (black-eyed pea) curry, and a sautéed spinach", "lunch_b": "Fish curry with rice and a cucumber salad", "nourishment_break_a": "A bowl of papaya with a small handful of roasted peanuts", "nourishment_break_b": "A glass of buttermilk with a small handful of roasted watermelon seeds", "dinner_a": "Corn-and-paneer stuffed dosa with chutney", "dinner_b": "Rice with a chicken curry and a sautéed pumpkin", "still_hungry": "A small bowl of sliced guava and orange with curd"}, {"day_number": 4, "title": "India''s real fluoride story — knowing your water", "notes": "High-fluoride groundwater has been reported across multiple parts of India. The risk is determined by the particular water source—not simply by living in a named state—and safe and unsafe sources can exist near one another. Long-term intake from an affected source can cause dental fluorosis while teeth are developing and, at sufficiently high exposure over many years, skeletal fluorosis. This is relevant to the whole household. Fluoride exposure while a child''s teeth are developing influences dental-fluorosis risk, while prolonged high exposure can also affect adult bone and joint health. If your household relies on a private borewell, hand pump or another groundwater source whose quality is uncertain, ask the local water-supply authority, panchayat or an appropriately recognised laboratory for the source''s current fluoride result. Do not rely on taste, appearance, a home filter''s marketing claim or a state-level list. If the result is high, follow local public-health guidance for a safe drinking and cooking-water source. Where groundwater fluoride is known to be high, use the safe water source recommended by the local health authority when preparing formula, drinks or food for the baby.", "breakfast_a": "Vegetable sevai upma with peanuts", "breakfast_b": "Egg-and-onion paratha", "lunch_a": "Rice, a chana dal curry, and a bhindi (okra) sabzi", "lunch_b": "Roti with a mutton curry and a methi (fenugreek) sabzi", "nourishment_break_a": "A sliced pear with a small handful of walnuts", "nourishment_break_b": "A small bowl of curd with a spoon of roasted sesame seeds", "dinner_a": "Kaddu chana with millet roti", "dinner_b": "Rice with a fish curry and a stir-fried spinach", "still_hungry": "A glass of buttermilk with a few mint leaves"}, {"day_number": 5, "title": "Fluoride toothpaste and adult dental care", "notes": "Brushing twice a day for about two minutes with fluoride toothpaste remains a standard part of adult dental care during pregnancy and breastfeeding. Spit out the toothpaste rather than swallowing it, and follow the product instructions or your dentist''s advice. Pregnancy and breastfeeding are not reasons to switch automatically to fluoride-free toothpaste. For your baby, toothpaste amount and concentration are age-specific. Follow local paediatric or dental guidance once teeth erupt; do not apply the adult instruction or an adult-sized amount to the baby.", "breakfast_a": "Methi-matar paneer with phulka", "breakfast_b": "Egg-and-spinach omelette with whole-wheat toast", "lunch_a": "Rice, a masoor dal curry, and a beans-and-peas sabzi", "lunch_b": "Roti with chicken curry and a sautéed capsicum", "nourishment_break_a": "A bowl of orange segments with a small handful of walnuts", "nourishment_break_b": "A glass of buttermilk with a small handful of roasted sunflower seeds", "dinner_a": "Moong-dal vegetable khichdi with curd", "dinner_b": "Rice with a mutton curry and a sautéed brinjal (eggplant)", "still_hungry": "A small bowl of curd with a sliced banana"}, {"day_number": 6, "title": "Away from home — water matters here too", "notes": "When travelling or eating out, the water behind your meal — used for cooking, tea, or ice — follows the same food-safety guidance as always: stick to water you trust. Bottled water is not automatically fluoride-free, and its fluoride concentration may not be stated unless the product makes a specific fluoride claim. If fluoride concentration matters because your usual source is known to be high, use a verified safe source rather than judging by packaging alone. This isn''t only a fluoride-specific caution — where your water comes from matters for more than one reason. Food safety: Paneer, curd, and any dairy-based item should be kept refrigerated or in an insulated bag with an ice pack until eaten, and eaten within about two hours at room temperature — sooner in hot weather. If carrying cooked egg, paneer, meat or another perishable food for later, keep it properly hot in a suitable insulated container or properly chilled with an ice pack — do not leave it merely warm for several hours. Reheat any packed dinner until steaming hot before eating.", "breakfast_a": "Mixed-vegetable and moong dal chilla, prepared fresh and eaten promptly", "breakfast_b": "Egg-and-vegetable sandwich, prepared fresh and eaten promptly", "lunch_a": "Horse-gram (kulthi) dal with rice and a cucumber salad", "lunch_b": "Home-packed chicken keema-matar curry with rice", "nourishment_break_a": "A fruit chaat (mixed seasonal fruit) with a small handful of roasted peanuts", "nourishment_break_b": "A small bowl of curd with a spoon of roasted sunflower seeds", "dinner_a": "Reheated palak (spinach) and moong dal curry with rice", "dinner_b": "Reheated paneer-and-mixed-vegetable curry with rice", "still_hungry": "A glass of milk with roasted chana and a few dates"}, {"day_number": 7, "title": "Reflection", "notes": "No forced choices today — a chance to notice which combinations from this week actually worked for you. Still in Settling into strength. This week''s mineral turned out to be one of the few in this whole series that doesn''t ask anything extra of your plate at all — the real story was your water, not your food, and something the whole household, not just your baby, may need to know.", "breakfast_a": "Whichever breakfast worked best for you this week", "breakfast_b": null, "lunch_a": "Whichever lunch you''d repeat", "lunch_b": null, "nourishment_break_a": "Whichever nourishment break suited you", "nourishment_break_b": null, "dinner_a": "Whichever dinner felt most manageable", "dinner_b": null, "still_hungry": "A familiar snack, if you''re still hungry"}]'::jsonb,
   'This week was mostly about noticing: did it feel different to learn about a nutrient that doesn''t ask you to change what you eat at all?',
   'Next week, this series continues through the nutrients that rarely make headlines but keep doing their quiet work regardless.')
on conflict (stage, week_number) do update set
  trimester = excluded.trimester,
  phase_label = excluded.phase_label,
  theme_title = excluded.theme_title,
  mantra = excluded.mantra,
  why_it_matters = excluded.why_it_matters,
  condition_notes = excluded.condition_notes,
  meat_fish_eggs_note = excluded.meat_fish_eggs_note,
  using_meals_note = excluded.using_meals_note,
  days = excluded.days,
  reflection = excluded.reflection,
  looking_ahead = excluded.looking_ahead;

-- postpartum week 39: Multivitamins, why your prenatal may not be the right bottle anymore
insert into nourish_week_content
  (stage, week_number, trimester, phase_label, theme_title, mantra,
   why_it_matters, condition_notes, meat_fish_eggs_note, using_meals_note,
   days, reflection, looking_ahead)
values
  ('postpartum',
   39,
   NULL,
   'Phase 4 of 6 — Settling into strength',
   'Multivitamins, why your prenatal may not be the right bottle anymore',
   '"The multivitamin that fit pregnancy isn''t automatically the one that fits now — this week is about checking, not guessing."',
   'This week doesn''t have a single reference figure to chase, because "multivitamin" isn''t one defined nutrient — it''s a product category, and what''s actually inside varies by brand. This week is about checking what you''re already taking, not adding anything new. A prenatal multivitamin is formulated around pregnancy''s specific needs. Several of those needs genuinely change after birth — some go down, some go up, and a few nutrients aren''t reliably included at all. Continuing the same bottle out of habit, without a fresh look, can mean missing something that actually matters now. Reference guidance: There is no single reference value for "a multivitamin" because it is a mixed product rather than one nutrient. Products sold as health supplements in India are generally covered by FSSAI''s health-supplement framework, but products, formulations and intended uses vary. Two bottles carrying similar front-label descriptions may contain very different nutrients and doses, so the actual ingredient panel matters more than the product name. Worth knowing: This week''s guidance is general — it doesn''t replace reading your specific product''s label or asking your care team or pharmacist to check it with you. If you''re unsure what you''re currently taking, bringing the bottle itself to your next appointment is more reliable than trying to remember the name. Every day below offers two distinct, individually balanced meals for each slot — pick whichever fits your day, your preferences, or what''s in your kitchen. If you have a diagnosed food allergy: If you have any diagnosed food allergy — including an allergy to egg, dairy, wheat, soy, peanut, tree nuts, seeds, fish or shellfish — avoid that food completely and choose an alternative you already tolerate. Do not trial a problem food to pursue this week''s nutrient. Do not automatically substitute seeds for nuts unless the seed is already known to be tolerated. If you are managing a health condition - If you take levothyroxine: iron and calcium — both common in multivitamins — can reduce its absorption when taken too close together. Keep at least four hours between levothyroxine and an iron- or calcium-containing supplement, unless your prescriber has given different instructions. Continue taking your thyroid medicine according to your prescribed timing. - If you have been diagnosed with a specific deficiency, or your care team has prescribed a particular supplement or dose — such as for postpartum anemia: follow that specific plan rather than adding a separate general multivitamin on top of it without checking. Do not add another iron-containing product without checking the combined dose — doses used to treat diagnosed anaemia may be higher than general supplement limits and should follow the prescribed plan. - If you eat little or no animal food: confirm that your vitamin B12 intake is reliable. Iron may also deserve attention depending on your diet, menstrual pattern, blood-loss history and test results. Check rather than assuming that a product labelled ''multivitamin'' supplies enough of either. - If you take a hair, skin or nail supplement: check whether it contains high-dose biotin. Biotin can interfere with some blood-test results, including certain thyroid tests. Tell the clinician and laboratory what you take before testing, and follow their instructions about whether and when to pause it — do not guess.',
   NULL,
   NULL,
   NULL,
   '[{"day_number": 1, "title": "What \"multivitamin\" actually means", "notes": "The word \"multivitamin\" isn''t defined the same precise way a single nutrient like iron or vitamin D is — it''s a mixed product, and what''s inside varies by brand. This week doesn''t ask you to eat toward a number; it asks you to actually check what you''re taking, and why.", "breakfast_a": "Oats-besan vegetable cheela with curd", "breakfast_b": "Egg-and-capsicum bhurji with roti", "lunch_a": "Brown-rice lemon pulao with black-chana sundal", "lunch_b": "Chicken vegetable stew with appam", "nourishment_break_a": "A sliced apple with a small handful of pumpkin seeds", "nourishment_break_b": "Makhana-peanut chaat", "dinner_a": "Vegetable litti with a lightly spiced dal", "dinner_b": "Fish tikka with vegetable millet pulao", "still_hungry": "A small bowl of curd with a few dates"}, {"day_number": 2, "title": "Why your iron target usually falls — but not always", "notes": "Iron needs generally fall after pregnancy in commonly used reference systems, partly because menstrual losses may not yet have resumed. But this does not mean every postpartum mother should stop iron. Blood loss during birth, postpartum anaemia, the return of periods, another pregnancy, dietary intake and recent blood-test results can all change what is appropriate. Continue any prescribed iron for the advised duration, and do not replace a treatment plan with a standard multivitamin.", "breakfast_a": "Vegetable akki roti with sambar", "breakfast_b": "Egg-and-onion uttapam", "lunch_a": "Barley and moong vegetable bowl", "lunch_b": "Mutton keema-stuffed capsicum with phulka", "nourishment_break_a": "A bowl of pomegranate with a small handful of almonds", "nourishment_break_b": "Corn, chana and vegetable chaat", "dinner_a": "Vegetable khichuri (mixed-dal khichdi) with curd", "dinner_b": "Chicken curry with red-rice dosa", "still_hungry": "A small bowl of fully cooked sprouts chaat with tomato and a squeeze of lemon"}, {"day_number": 3, "title": "Where the target rises instead — vitamin A and E", "notes": "In the US National Academies reference system, the recommended intake for vitamin A rises from 770 mcg RAE during pregnancy to 1,300 mcg RAE during lactation, and vitamin E rises from 15 mg to 19 mg. These figures do not mean that every breastfeeding mother needs a higher-dose supplement. Food intake, the form and amount already present in the product, and the safety of the combined dose still matter. In particular, do not add a separate high-dose vitamin A or vitamin E supplement simply because you are breastfeeding.", "breakfast_a": "Moong dal pesarattu with ginger chutney", "breakfast_b": "Boiled egg with vegetable upma", "lunch_a": "Dal-palak handvo with green chutney", "lunch_b": "Fish moilee with steamed rice and a cucumber salad", "nourishment_break_a": "A seasonal vitamin-A-rich fruit (such as mango or papaya, whichever is in season) with a small handful of sunflower seeds", "nourishment_break_b": "Hummus with cucumber and whole-wheat lavash", "dinner_a": "Vegetable-and-paneer stuffed paratha with curd", "dinner_b": "Chicken curry with vegetable millet khichdi", "still_hungry": "A small bowl of curd with a sliced banana"}, {"day_number": 4, "title": "Four useful lines to check on your label", "notes": "Four useful label checks are choline, vitamin B12, vitamin D and iodine. Choline is absent or present only in modest amounts in many multivitamins. Vitamin B12 deserves particular attention if you eat little or no animal food. Vitamin D amounts can vary, and iodine may not appear in every product. Their absence does not mean you should automatically add four separate supplements — the first step is simply to see what your current product contains. If you have thyroid disease, do not add a separate iodine supplement merely because the multivitamin does not contain iodine; your thyroid treatment and total intake need to be considered together.", "breakfast_a": "Vegetable dhokla with green chutney and curd", "breakfast_b": "Egg-and-vegetable dosa", "lunch_a": "Rajgira roti with a mixed-bean curry", "lunch_b": "Mutton curry with brown-rice pulao and a cucumber-tomato salad", "nourishment_break_a": "A wedge of watermelon with a small handful of walnuts", "nourishment_break_b": "A small bowl of curd with a spoon of chia seeds", "dinner_a": "Vegetable-and-soy khichdi", "dinner_b": "Fish curry with vegetable bajra khichdi", "still_hungry": "A glass of buttermilk with a pinch of roasted cumin"}, {"day_number": 5, "title": "When the routine postpartum iron period has ended", "notes": "Under Anaemia Mukt Bharat, daily iron–folic acid containing 60 mg elemental iron and 500 mcg folic acid is recommended from the second trimester, through the remainder of pregnancy, and for 180 days after birth. By Postpartum Week 39, that routine six-month period has usually ended. This is a useful point to check rather than continue, restart or double the tablets automatically. If you were told to continue because of anaemia, heavy bleeding or another clinical reason, follow that treatment plan. If you remain unusually tired, breathless, dizzy or weak, seek assessment rather than assuming that a general multivitamin will correct the cause.", "breakfast_a": "Vegetable idli with sambar", "breakfast_b": "Egg-and-tomato omelette with toast", "lunch_a": "Millet khichdi with a mixed-vegetable raita", "lunch_b": "Chicken stew with brown rice and a cucumber salad", "nourishment_break_a": "A sliced pear with a small handful of pistachios", "nourishment_break_b": "Seasonal fruit with unsweetened hung curd", "dinner_a": "Vegetable thepla with a hung-curd dip", "dinner_b": "Vegetable-rich mutton stew with appam", "still_hungry": "A small bowl of curd with a few almonds"}, {"day_number": 6, "title": "Reading a label, away from home", "notes": "The RDA or %DV shown on a label may use a general adult reference or another reference required for that product; it should not automatically be assumed to equal the breastfeeding target used elsewhere in this programme. When you''re out and can''t check a label in the moment, that''s fine — this is a once-in-a-while check, not a daily calculation. Photograph every label panel — including any side panel or peel-back section — and check: - The serving size — one tablet, two tablets, or another amount. - The amount per full daily serving, not merely per tablet. - Whether it contains iron, calcium, iodine, vitamin D, vitamin B12 and choline. - Whether another supplement you take repeats any of the same nutrients. - The expiry date and the product''s storage instructions. Food safety: Paneer, curd, and any dairy-based item should be kept refrigerated or in an insulated bag with an ice pack until eaten, and eaten within about two hours at room temperature — sooner in hot weather. If carrying cooked egg, paneer, meat or another perishable food for later, keep it properly hot in a suitable insulated container or properly chilled with an ice pack — do not leave it merely warm for several hours. Reheat any packed dinner until steaming hot before eating.", "breakfast_a": "Paneer-and-vegetable paratha, prepared fresh and eaten promptly", "breakfast_b": "Egg-and-vegetable frankie, prepared fresh and eaten promptly", "lunch_a": "Chana-and-vegetable wrap with curd", "lunch_b": "Home-packed mutton curry with brown rice and a cucumber salad", "nourishment_break_a": "A fruit chaat (mixed seasonal fruit) with a small handful of roasted chana", "nourishment_break_b": "A small bowl of curd with a spoon of roasted watermelon seeds", "dinner_a": "Reheated mixed-vegetable and soy curry with rice", "dinner_b": "Reheated chicken curry with vegetable bajra khichdi", "still_hungry": "A glass of milk with a date"}, {"day_number": 7, "title": "Reflection", "notes": "No forced choices today — a chance to notice which combinations from this week actually worked for you. Still in Settling into strength. This week''s real task wasn''t a plate — it was five minutes with your own supplement bottle, and knowing that it''s genuinely all right for what fits your body right now to be different from what fit it during pregnancy.", "breakfast_a": "Whichever breakfast worked best for you this week", "breakfast_b": null, "lunch_a": "Whichever lunch you''d repeat", "lunch_b": null, "nourishment_break_a": "Whichever nourishment break suited you", "nourishment_break_b": null, "dinner_a": "Whichever dinner felt most manageable", "dinner_b": null, "still_hungry": "A familiar snack, if you''re still hungry"}]'::jsonb,
   'This week was mostly about noticing: when did you last actually read your own supplement''s label, rather than just remembering to take it?',
   'Next week, this series continues through the nutrients that rarely make headlines but keep doing their quiet work regardless.')
on conflict (stage, week_number) do update set
  trimester = excluded.trimester,
